{
  "@type": "PermissionSpecificationSet",
  "@baseType": "PermissionSpecificationSet",
  "name": "CSP",
  "involvementRole": "CSP",
  "description": "CSP retail (RedBrand brand) permissions for retail product inventory",
  "permissionSpecification": [
    {
      "@type": "PermissionSpecification",
      "name": "RedBrand:read",
      "description": "Read access to RedBrand product inventory resources",
      "function": "productInventory",
      "action": "Read"
    },
    {
      "@type": "PermissionSpecification",
      "name": "RedBrand:write",
      "description": "Write access to RedBrand product inventory resources",
      "function": "productInventory",
      "action": "ReadWrite"
    }
  ]
}

